import React, { useState, useEffect } from 'react';
import { useSocket } from '../context/SocketContext';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Activity, Clock, CheckCircle, XCircle, AlertTriangle } from 'lucide-react';

const Dashboard = () => {
  const { isConnected } = useSocket();
  const [pipelines, setPipelines] = useState([]);
  const [metrics, setMetrics] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadDashboardData();
    const interval = setInterval(loadDashboardData, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const loadDashboardData = async () => {
    try {
      // Load pipelines - use relative URL since nginx will proxy
      const pipelinesResponse = await fetch('/api/pipelines');
      const pipelinesData = await pipelinesResponse.json();
      setPipelines(pipelinesData.pipelines || []);

      // Load metrics - use relative URL since nginx will proxy
      const metricsResponse = await fetch('/api/metrics/dashboard-summary');
      const metricsData = await metricsResponse.json();
      setMetrics(metricsData);

      setLoading(false);
    } catch (error) {
      console.error('Failed to load dashboard data:', error);
      setLoading(false);
    }
  };

  const calculateMetrics = () => {
    if (!pipelines.length) return {};

    const total = pipelines.length;
    const success = pipelines.filter(p => p.status === 'success').length;
    const failed = pipelines.filter(p => p.status === 'failed').length;
    const pending = pipelines.filter(p => p.status === 'pending').length;
    const successRate = Math.round((success / total) * 100);
    const avgBuildTime = Math.round(
      pipelines.reduce((sum, p) => sum + (p.build_time || 0), 0) / total
    );

    return { total, success, failed, pending, successRate, avgBuildTime };
  };

  const chartData = [
    { name: 'Success', value: calculateMetrics().success, color: '#10B981' },
    { name: 'Failed', value: calculateMetrics().failed, color: '#EF4444' },
    { name: 'Pending', value: calculateMetrics().pending, color: '#F59E0B' },
  ];

  const recentPipelines = pipelines.slice(0, 5);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
          <p className="text-gray-600">Real-time CI/CD pipeline monitoring</p>
        </div>
        <div className="flex items-center space-x-2">
          <div className={`h-2 w-2 rounded-full ${isConnected ? 'bg-green-400' : 'bg-red-400'}`} />
          <span className="text-sm text-gray-600">
            {isConnected ? 'Connected' : 'Disconnected'}
          </span>
        </div>
      </div>

      {/* Metrics Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white rounded-lg shadow p-6">
          <div className="flex items-center">
            <div className="p-2 bg-blue-100 rounded-lg">
              <Activity className="h-6 w-6 text-blue-600" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Total Pipelines</p>
              <p className="text-2xl font-bold text-gray-900">{calculateMetrics().total}</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <div className="flex items-center">
            <div className="p-2 bg-green-100 rounded-lg">
              <CheckCircle className="h-6 w-6 text-green-600" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Success Rate</p>
              <p className="text-2xl font-bold text-gray-900">{calculateMetrics().successRate}%</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <div className="flex items-center">
            <div className="p-2 bg-yellow-100 rounded-lg">
              <Clock className="h-6 w-6 text-yellow-600" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Avg Build Time</p>
              <p className="text-2xl font-bold text-gray-900">{calculateMetrics().avgBuildTime}s</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <div className="flex items-center">
            <div className="p-2 bg-red-100 rounded-lg">
              <XCircle className="h-6 w-6 text-red-600" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600">Failed Pipelines</p>
              <p className="text-2xl font-bold text-gray-900">{calculateMetrics().failed}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Pipeline Status Distribution</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={chartData}
                cx="50%"
                cy="50%"
                outerRadius={80}
                dataKey="value"
                label={({ name, value }) => `${name}: ${value}`}
              >
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-medium text-gray-900 mb-4">Recent Build Times</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={recentPipelines}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="build_time" fill="#3B82F6" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Recent Pipelines */}
      <div className="bg-white rounded-lg shadow">
        <div className="px-6 py-4 border-b border-gray-200">
          <h3 className="text-lg font-medium text-gray-900">Recent Pipelines</h3>
        </div>
        <div className="divide-y divide-gray-200">
          {recentPipelines.map((pipeline) => (
            <div key={pipeline.id} className="px-6 py-4">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-sm font-medium text-gray-900">{pipeline.name}</h4>
                  <p className="text-sm text-gray-500">
                    Branch: {pipeline.branch} | Commit: {pipeline.commit_hash}
                  </p>
                </div>
                <div className="flex items-center space-x-4">
                  <span className="text-sm text-gray-500">{pipeline.build_time}s</span>
                  <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                    pipeline.status === 'success' ? 'bg-green-100 text-green-800' :
                    pipeline.status === 'failed' ? 'bg-red-100 text-red-800' :
                    'bg-yellow-100 text-yellow-800'
                  }`}>
                    {pipeline.status}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
